class Doc(HTMLParser):
 def __init__(self,html):
  super().__init__(convert_charrefs=True);self.tags=[];self.text=[];self.skip=0;self.stack=[];self.errors=[];self.feed(html)
 def handle_starttag(self,t,aa):
  self.tags.append((t,dict(aa)))
  if t in ('script','style'): self.skip+=1
  if t not in ('area','base','br','col','embed','hr','img','input','link','meta','param','source','track','wbr'):self.stack.append(t)
 def handle_startendtag(self,t,a):self.tags.append((t,dict(a)))
 def handle_endtag(self,t):
  if t in ('script','style'):self.skip-=1
  if not self.stack or self.stack[-1]!=t:self.errors.append('Unexpected closing '+t)
  else:self.stack.pop()
 def handle_data(self,s):
  if not self.skip:self.text.append(s)

